static int failures;
static struct kof_editor E;
static char root[300];
static const char *builder = "build/release/bin/ksigbuilder";
static const char *dbdir = "build/test/databases-sigs";

#define OKF(cond, ...) do { if (!(cond)) { printf("  FAIL %s:%d: ", __FILE__, __LINE__); printf(__VA_ARGS__); printf("\n"); failures++; } } while (0)

static char *slurp(const char *path, size_t *n)
{
	FILE *f = fopen(path, "rb");
	char *b;
	long L;

	if (!f)
		return NULL;
	fseek(f, 0, SEEK_END);
	L = ftell(f);
	fseek(f, 0, SEEK_SET);
	b = malloc((size_t)L + 1u);
	if (b && fread(b, 1, (size_t)L, f) != (size_t)L) {
		free(b);
		b = NULL;
	}
	fclose(f);
	if (b) {
		b[L] = 0;
		if (n)
			*n = (size_t)L;
	}
	return b;
}

static int put_file(const char *path, const void *p, size_t n)
{
	FILE *f = fopen(path, "wb");

	if (!f)
		return 0;
	if (n && fwrite(p, 1, n, f) != n) {
		fclose(f);
		return 0;
	}
	return fclose(f) == 0;
}

static unsigned count_files(const char *dir)
{
	DIR *d = opendir(dir);
	struct dirent *de;
	unsigned n = 0;

	while (d && (de = readdir(d)) != NULL)
		n += de->d_name[0] != '.';
	if (d)
		closedir(d);
	return n;
}

static void today_window(char *lo, char *hi, size_t cap, void (*run)(void))
{
	time_t t = time(NULL);
	struct tm tmv;

	localtime_r(&t, &tmv);
	strftime(lo, cap, "%Y-%m-%d", &tmv);
	run();
	t = time(NULL);
	localtime_r(&t, &tmv);
	strftime(hi, cap, "%Y-%m-%d", &tmv);
}

/* ---- the printer ------------------------------------------------------------------------------------------------------ */

static const char *const SHA_A = "9f86d081884c7d659a2feaa0c55ad015a3bf4f1b2b0b822cd15d6c15b0f00a08";
static const char *const SHA_B = "2c26b46b68ffc68ff99b453c1d30413413422d706483bfa0f98a5e886266e7ae";
#define BODY "KOF_DIAG_NAME(x_00);\nKOF_DIAG_FAMILY(\"Mirai\");\n"

static char *head(const char *text, const char *name, const char *sha, const char *who, const char *date, int *how)
{
	struct kof_dsrc_meta m;
	size_t n = 0;
	int h = 0;
	char *r;

	memset(&m, 0, sizeof m);
	m.name = name;
	m.sha256 = sha;
	m.who = who;
	m.date = date;
	r = kof_dsrc_head(text, strlen(text), &m, &h, &n);
	if (r && strlen(r) != n)
		printf("  FAIL length %zu != %zu\n", strlen(r), n), failures++;
	if (how)
		*how = h;
	return r;
}

static void engine_line(char *out, size_t cap)
{
	snprintf(out, cap, "Engine:      db format %u.%u, module ABI %u", (unsigned)KOF_PACK_MAJOR, (unsigned)KOF_PACK_MINOR,
		 (unsigned)KOFSIG_ABI_VERSION);
}

static void printer(void)
{
	int how = 0, h2 = 0;
	char want[200], eng[120], *t, *b, *c;
	size_t n = 0;
	struct kof_dsrc_meta m = { "s.bin", SHA_A, "me", "2026-10-31" };

	t = head(BODY, "sample.bin", SHA_A, "dmknght", "2026-10-31", &how);
	OKF(t && how == KOF_DSRC_HEAD_NEW && !strncmp(t, "/*\n * Generated by KOFViewer.\n *\n", 33), "a new block, opened as the old one");
	if (t) {
		snprintf(want, sizeof want, " * Test sample: sample.bin  sha256:%s\n", SHA_A);
		engine_line(eng, sizeof eng);
		OKF(strstr(t, want) && strstr(t, " * Researcher:  dmknght\n") && strstr(t, " * Created 2026-10-31, updated 2026-10-31\n") &&
		    strstr(t, eng), "name+sha256, researcher, dates, the engine's constants");
		OKF(strstr(t, " */\n\n" BODY) && !strcmp(strstr(t, " */\n\n" BODY) + 5, BODY), "the text follows untouched");
	}
	free(t);
	t = head(BODY, NULL, NULL, NULL, "2026-10-31", &how);
	OKF(t && !strstr(t, "Test sample") && !strstr(t, "Researcher") && !strstr(t, "sha256"), "a field not known is not written");
	free(t);
	t = head(BODY, "a*/ evil(); /*b", "dead*/beef", NULL, "2026-10-31", &how);
	OKF(t && strstr(t, "*/") && strstr(strstr(t, "*/") + 2, "*/") == NULL, "hostile characters never close the comment early");
	free(t);
	/* refresh: Created kept, updated moves, every other byte kept, one day twice is the identity */
	t = head(BODY, "sample.bin", SHA_A, "dmknght", "2026-10-31", &how);
	b = head(t, "x", SHA_B, "y", "2026-11-05", &how);
	OKF(b && how == KOF_DSRC_HEAD_REFRESHED && strstr(b, " * Created 2026-10-31, updated 2026-11-05\n") && strstr(b, SHA_A) && !strstr(b, SHA_B),
	    "Created kept, updated moved, the other lines as they were");
	OKF(b && !strcmp(strstr(b, BODY), BODY), "the text after the block is kept");
	c = head(b, "x", SHA_B, "y", "2026-11-05", &h2);
	OKF(c && !strcmp(b, c), "refreshing twice on one day changes nothing");
	free(c);
	free(b);
	free(t);
	/* a block that is not the tool's is not touched */
	{
		static const char *const hand[] = { "/* my notes */\n" BODY, "/*\n * Test sample: forged\n */\n" BODY, "// Generated by KOFViewer.\n" BODY };
		unsigned i;

		for (i = 0; i < 3u; i++) {
			t = kof_dsrc_head(hand[i], strlen(hand[i]), &m, &how, &n);
			OKF(t && how == KOF_DSRC_HEAD_HAND && n == strlen(hand[i]) && !memcmp(t, hand[i], n), "hand header %u is not touched", i);
			free(t);
		}
	}
	/* the patcher passes the block through */
	{
		char *p, *tt = head(BODY "KOF_DIAG_TAG(\"flood\");\n", "s.bin", SHA_A, NULL, "2026-10-31", NULL);
		struct kof_dsrc *d = calloc(1, sizeof *d);

		OKF(tt && kof_dsrc_parse(tt, strlen(tt), d, NULL) == 0, "a text with the block reads");
		p = tt ? kof_dsrc_patch(tt, strlen(tt), d, &n) : NULL;
		OKF(p && n == strlen(tt) && !memcmp(p, tt, n), "kof_dsrc_patch keeps the block");
		free(p);
		free(tt);
		free(d);
	}
}

/* ---- Save --------------------------------------------------------------------------------------------------------------- */

static void write_catalogs(const char *base)
{
	struct kof_famcat_fam fam[8];
	struct kof_famcat_var var[8];
	struct kof_catstore *st = calloc(1, sizeof *st);
	struct kof_tagcat_tag tag[8];
	struct kof_tagcat tc;
	struct kof_famcat c;
	char dir[500];
	uint32_t f;

	snprintf(dir, sizeof dir, "%s/pathogens", base);
	kof_mkdir(dir, 0700);
	kof_famcat_init(&c, fam, 8, var, 8);
	kof_catstore_init(st);
	(void)kof_famcat_add_family(&c, "Mirai", NULL, (1u << KOF_MALTYPE_BOTNET) | (1u << KOF_MALTYPE_ROOTKIT), &f);
	(void)kof_famcat_save(&c, st, dir);
	snprintf(dir, sizeof dir, "%s/syndromes", base);
	kof_mkdir(dir, 0700);
	kof_tagcat_init(&tc, tag, 8);
	kof_catstore_init(st);
	(void)kof_tagcat_add(&tc, "flood", 1u << KOF_DISEASE_ACT_SCAN, 1u << KOF_DISEASE_OBJ_NETWORK, NULL);
	(void)kof_tagcat_add(&tc, "c2", 1u << KOF_DISEASE_ACT_C2, 1u << KOF_DISEASE_OBJ_NETWORK, NULL);
	(void)kof_tagcat_save(&tc, st, dir);
	free(st);
}

/* One condition over one text marker: the smallest draft that Save writes with its detection part. */
static void the_draft(void)
{
	struct decl *d;
	struct group *g;
	struct cond *c;

	memset(&E.dr, 0, sizeof E.dr);
	snprintf(E.dr.family, sizeof E.dr.family, "Mirai");
	snprintf(E.dr.variant, sizeof E.dr.variant, "Mirai_A");
	E.dr.fmt_mask = 1u << KOF_FMT_ELF;
	d = decl_push(&E);
	memset(d, 0, sizeof *d);
	d->bytes = malloc(12);
	memcpy(d->bytes, "alpha-marker", 12);
	d->nbytes = d->len = 12;
	d->grp = 1u;
	g = &E.dr.grp[E.dr.n_grp++];
	memset(g, 0, sizeof *g);
	g->kind = (uint8_t)GRP_KIND_STR;
	g->rule = 1;
	g->mask = KOF_SCAN_ALL;
	c = &E.dr.cnd[E.dr.n_cnd++];
	memset(c, 0, sizeof *c);
	snprintf(c->expr, sizeof c->expr, "1");
	c->utype = (uint8_t)(KOF_MALTYPE_BOTNET + 1u);
	snprintf(c->tag, sizeof c->tag, "flood");
}

static void drop_draft(void)
{
	uint32_t i;

	for (i = 0; i < E.dr.n_decl; i++)
		free(E.dr.decl[i].bytes);
	free(E.dr.decl);
	free(E.dr.blk);
	memset(&E.dr, 0, sizeof E.dr);
}

static struct object OB[4];
static uint32_t NOB;

static void objects_reset(void)
{
	memset(OB, 0, sizeof OB);
	NOB = 0;
	E.obj = OB;
	E.n_obj = &NOB;
	E.cur = 0;
}

static const char *const FILE_NAME = "botnet_mirai_flood_01.c";

static char *saved(const char *dir, int *wrote)
{
	char msg[300], path[700];

	kof_mkdir(dir, 0700);
	*wrote = draft_generate(&E, dir, msg, sizeof msg);
	if (*wrote < 0)
		printf("    Save said: %s\n", msg);
	snprintf(path, sizeof path, "%s/%s", dir, FILE_NAME);
	return slurp(path, NULL);
}

static char gdir[512];
static char *g_text;
static int g_wrote;
static void do_save(void) { g_text = saved(gdir, &g_wrote); }

static char *save_in(const char *tag, char *lo, char *hi)
{
	snprintf(gdir, sizeof gdir, "%s/%s", root, tag);
	the_draft();
	today_window(lo, hi, 16, do_save);
	drop_draft();
	return g_text;
}

static void save_header(void)
{
	char lo[16], hi[16], want[400], eng[120];
	char *t;

	objects_reset();
	snprintf(OB[0].name, sizeof OB[0].name, "/some/dir/sample.bin");
	snprintf(OB[0].sha256, sizeof OB[0].sha256, "%s", SHA_A);
	NOB = 1;
	t = save_in("s_top", lo, hi);
	OKF(g_wrote == 1 && t, "Save writes the file");
	if (t) {
		snprintf(want, sizeof want, " * Test sample: sample.bin  sha256:%s\n", SHA_A);
		OKF(!strncmp(t, "/*\n * Generated by KOFViewer.\n", 30) && strstr(t, want), "the header names the file and its sha256");
		snprintf(want, sizeof want, " * Created %s, updated %s\n", lo, lo);
		snprintf(eng, sizeof eng, " * Created %s, updated %s\n", hi, hi);
		OKF(strstr(t, want) || strstr(t, eng), "the dates are the host's date (window %s .. %s)", lo, hi);
		engine_line(eng, sizeof eng);
		OKF(strstr(t, eng) && !strstr(t, "Researcher"), "the engine's numbers; no researcher (no source for one)");
		free(t);
	}
	objects_reset();
	t = save_in("s_none", lo, hi);
	OKF(t && !strstr(t, "Test sample") && !strstr(t, "sha256"), "a draft with no object writes no sample line");
	free(t);
}

static void save_twice_and_hand(void)
{
	char lo[16], hi[16], d2[600], msg[300], path[700];
	char *t, *h, *again;

	objects_reset();
	snprintf(OB[0].name, sizeof OB[0].name, "sample.bin");
	snprintf(OB[0].sha256, sizeof OB[0].sha256, "%s", SHA_A);
	NOB = 1;
	t = save_in("s_twice", lo, hi);
	the_draft();
	OKF(draft_generate(&E, gdir, msg, sizeof msg) == 0 && count_files(gdir) == 1u, "Save again finds the file: %s", msg);
	snprintf(path, sizeof path, "%s/%s", gdir, FILE_NAME);
	again = slurp(path, NULL);
	OKF(t && again && !strcmp(t, again), "and leaves it as it was");
	drop_draft();
	snprintf(d2, sizeof d2, "%s/s_hand", root);
	kof_mkdir(d2, 0700);
	if (t) {
		const char *body = strstr(t, "KOF_DIAG_NAME");
		size_t hn = strlen("/* by hand */\n\n") + strlen(body);

		h = malloc(hn + 1u);
		snprintf(h, hn + 1u, "/* by hand */\n\n%s", body);
		snprintf(path, sizeof path, "%s/%s", d2, FILE_NAME);
		OKF(put_file(path, h, hn), "a file with a hand header is put in the tree");
		the_draft();
		OKF(draft_generate(&E, d2, msg, sizeof msg) == 0 && count_files(d2) == 1u, "Save finds it too: %s", msg);
		free(again);
		again = slurp(path, NULL);
		OKF(again && !strcmp(again, h), "the hand header is not overwritten");
		drop_draft();
		free(h);
	}
	free(again);
	free(t);
}

/* ---- the builder -------------------------------------------------------------------------------------------------------- */

struct scene {
	char base[400], art[400], db[400], err[440];
};

static void scene_new(struct scene *s, const char *tag)
{
	char a[500], p[500];
	size_t n = 0;
	char *b;

	snprintf(s->base, sizeof s->base, "%s/%s_base", root, tag);
	snprintf(s->art, sizeof s->art, "%s/%s_art", root, tag);
	snprintf(s->db, sizeof s->db, "%s/%s_db", root, tag);
	snprintf(s->err, sizeof s->err, "%s/%s_err.txt", root, tag);
	kof_mkdir(s->base, 0700);
	kof_mkdir(s->art, 0700);
	kof_mkdir(s->db, 0700);
	snprintf(p, sizeof p, "%s/diagnoses", s->base);
	kof_mkdir(p, 0700);
	write_catalogs(s->base);
	snprintf(a, sizeof a, "%s/sigs-any.ksig", dbdir);
	snprintf(p, sizeof p, "%s/sigs-any.ksig", s->db);
	b = slurp(a, &n);
	if (b)
		(void)put_file(p, b, n);
	free(b);
}

static int build(struct scene *s)
{
	char cmd[4400];

	snprintf(cmd, sizeof cmd, "%s --tree '%s' '%s' '%s' --pathogens '%s/pathogens' --syndromes '%s/syndromes' --basedir '%s' "
		 ">'%s.out' 2>'%s'", builder, s->base, s->art, s->db, s->base, s->base, s->base, s->err, s->err);
	return system(cmd);
}

/* What the builder printed, with the scene's own directory name taken out (it is the only thing that may differ). */
static int same_files(const char *a, const char *b)
{
	char cmd[1400];

	snprintf(cmd, sizeof cmd, "diff -r '%s' '%s' >/dev/null 2>&1", a, b);
	return system(cmd) == 0;
}

static void builds_the_same(void)
{
	struct scene A, B, C;
	char lo[16], hi[16], p[600];
	char *t, *body;
	size_t bn;
	int wrote;

	objects_reset();
	snprintf(OB[0].name, sizeof OB[0].name, "sample.bin");
	snprintf(OB[0].sha256, sizeof OB[0].sha256, "%s", SHA_A);
	NOB = 1;
	scene_new(&A, "withhead");
	scene_new(&B, "nohead");
	scene_new(&C, "handhead");
	snprintf(gdir, sizeof gdir, "%s/diagnoses", A.base);
	the_draft();
	today_window(lo, hi, 16, do_save);
	drop_draft();
	t = g_text;
	wrote = g_wrote;
	OKF(wrote == 1 && t && !strncmp(t, "/*\n * Generated by KOFViewer.", 29), "the diagnose to build carries the header");
	if (!t)
		return;
	body = strstr(t, "KOF_DIAG_NAME");
	bn = strlen(body);
	snprintf(p, sizeof p, "%s/diagnoses/%s", B.base, FILE_NAME);
	OKF(put_file(p, body, bn), "the same text without the header");
	{
		static const char hand[] = "/* a hand header: KOF_DIAG_NAME(zzz); kof_diag(q); \"x\" */\n\n";
		char *c = malloc(sizeof hand + bn);

		memcpy(c, hand, sizeof hand - 1u);
		memcpy(c + sizeof hand - 1u, body, bn);
		snprintf(p, sizeof p, "%s/diagnoses/%s", C.base, FILE_NAME);
		OKF(put_file(p, c, sizeof hand - 1u + bn), "and under a hand header");
		free(c);
	}
	OKF(build(&A) == 0 && build(&B) == 0 && build(&C) == 0, "the builder takes all three");
	OKF(count_files(A.art) > 0u, "and made artifacts");
	OKF(same_files(A.art, B.art) && same_files(A.db, B.db), "with the header the artifacts are the same bytes as without it");
	OKF(same_files(A.art, C.art) && same_files(A.db, C.db), "and under a hand header");
	{
		char cmd[2000];

		snprintf(cmd, sizeof cmd, "cmp -s '%s' '%s' && cmp -s '%s' '%s'", A.err, B.err, A.err, C.err);
		OKF(system(cmd) == 0, "the builder says the same thing: no warning is added by the comment");
	}
	free(t);
}

int main(void)
{
	if (access(builder, X_OK) != 0) {
		printf("diag_head: %s is not built\n", builder);
		return 2;
	}
	snprintf(root, sizeof root, "build/kof_diagmeta_XXXXXX");
	if (!mkdtemp(root)) {
		printf("diag_head: cannot make a scratch directory\n");
		return 2;
	}
	printer();
	save_header();
	save_twice_and_hand();
	builds_the_same();
	if (!failures) {
		char cmd[400];

		snprintf(cmd, sizeof cmd, "rm -rf '%s'", root);
		(void)system(cmd);
	}
	if (failures) {
		printf("diag_head: %d FAIL\n", failures);
		return 1;
	}
	printf("diag_head: ok\n");
	return 0;
}
